const allItems = $input.all().map(i => i.json);
const seen = new Set();
const cleaned = [];

for (const item of allItems) {
    if (!item.title || item.title === '__EMPTY__') continue;

    const normalizedTitle = item.title
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim();

    if (seen.has(normalizedTitle)) continue;
    seen.add(normalizedTitle);

    cleaned.push({
        json: {
            title: item.title,
            description: (item.description || '').substring(0, 300),
            price: item.price || 0,
            price_text: item.price_text || '',
            higher_price: item.higher_price || 0,
            search_keyword: item.search_keyword || item.fl_category || '',
            offers_count: item.offers_count || 0,
            payer_stats: item.payer_stats || '',
            url: item.url || '',
            date: item.date || ''
        }
    });
}

cleaned.sort((a, b) => (b.json.price || 0) - (a.json.price || 0));
return cleaned;

// ===== ФОРМИРУЕМ БАТЧ ДЛЯ LLM =====
const items = $input.all();
const batch = items.map((item, i) => ({
    id: i,
    title: item.json.title,
    description: item.json.description,
    price: item.json.price,
    keyword: item.json.search_keyword
}));

return [{ json: { batch: JSON.stringify(batch, null, 2), count: items.length } }];

// ===== МЕРЖИМ РЕЗУЛЬТАТЫ LLM С ОРИГИНАЛЬНЫМИ ДАННЫМИ =====
const llmResponse = $input.first().json;

let classifications;
try {
    // Универсальный поиск — ищем results в любой структуре
    const raw = JSON.stringify(llmResponse);

    // Находим {"results": [...]} в любом месте ответа
    const match = raw.match(/"results"\s*:\s*\[/);
    if (!match) throw new Error('No results array found');

    // Извлекаем JSON начиная с найденного results
    const startIdx = raw.lastIndexOf('{', match.index);
    let depth = 0;
    let endIdx = startIdx;
    for (let i = startIdx; i < raw.length; i++) {
        if (raw[i] === '{' || raw[i] === '[') depth++;
        if (raw[i] === '}' || raw[i] === ']') depth--;
        if (depth === 0) { endIdx = i + 1; break; }
    }

    let jsonStr = raw.substring(startIdx, endIdx);
    // Убираем экранирование если строка была внутри другой строки
    if (jsonStr.includes('\\"')) {
        jsonStr = jsonStr.replace(/\\"/g, '"').replace(/\\n/g, ' ');
    }

    const parsed = JSON.parse(jsonStr);
    classifications = parsed.results;
} catch(e) {
    return [{ json: { error: 'LLM parse failed: ' + e.message, raw: JSON.stringify(llmResponse).substring(0, 1000) } }];
}

// Достаём оригинальные данные из батча
const batchItems = $('Batch by 15').all();

const results = [];
for (const cls of classifications) {
    const original = batchItems[cls.id]?.json || {};

    results.push({
        json: {
            title: original.title || '',
            description: original.description || '',
            price: original.price || 0,
            price_text: original.price_text || '',
            search_keyword: original.search_keyword || '',
            url: original.url || '',
            category: cls.category || 'other',
            subcategory: cls.subcategory || '',
            complexity: cls.complexity || 'medium',
            can_automate: cls.can_automate || false
        }
    });
}

return results;

// ===== ФИНАЛЬНАЯ АГРЕГАЦИЯ =====
// Считаем статистику по категориям

const allItems = $('Merge LLM + Original').all().map(i => i.json);

const groups = {};
for (const item of allItems) {
    if (item.error) continue;
    const cat = item.category || 'other';

    if (!groups[cat]) {
        groups[cat] = {
            category: cat,
            count: 0,
            total_price: 0,
            prices: [],
            subcategories: {},
            examples: [],
            automatable: 0,
            complexity: { simple: 0, medium: 0, complex: 0 },
            keywords: {}
        };
    }

    const g = groups[cat];
    g.count++;

    if (item.price) {
        g.prices.push(item.price);
        g.total_price += item.price;
    }

    if (item.can_automate) g.automatable++;
    if (item.complexity) g.complexity[item.complexity] = (g.complexity[item.complexity] || 0) + 1;

    // Подкатегории
    const sub = item.subcategory || 'прочее';
    g.subcategories[sub] = (g.subcategories[sub] || 0) + 1;

    // Ключевые слова
    const kw = item.search_keyword || 'unknown';
    g.keywords[kw] = (g.keywords[kw] || 0) + 1;

    // Примеры (макс 3)
    if (g.examples.length < 3) {
        g.examples.push(item.title.substring(0, 80));
    }
}

// Формируем выход
const output = Object.values(groups)
    .map(g => {
        const avgPrice = g.prices.length 
            ? Math.round(g.total_price / g.prices.length) 
            : 0;
        const medianPrice = g.prices.length 
            ? g.prices.sort((a,b) => a-b)[Math.floor(g.prices.length/2)] 
            : 0;

        return {
            category: g.category,
            count: g.count,
            avg_price: avgPrice,
            median_price: medianPrice,
            automatable_pct: Math.round(g.automatable / g.count * 100),
            top_subcategories: Object.entries(g.subcategories)
                .sort((a,b) => b[1] - a[1])
                .slice(0, 5)
                .map(([name, cnt]) => `${name} (${cnt})`)
                .join('; '),
            top_keywords: Object.entries(g.keywords)
                .sort((a,b) => b[1] - a[1])
                .slice(0, 5)
                .map(([name, cnt]) => `${name} (${cnt})`)
                .join('; '),
            examples: g.examples.join(' | '),
            complexity_breakdown: `simple:${g.complexity.simple || 0} med:${g.complexity.medium || 0} complex:${g.complexity.complex || 0}`
        };
    })
    .sort((a,b) => b.count - a.count);

return output.map(item => ({ json: item }));
